For `f(x) = relu(x)^3`, the derivative is `d/dx[relu(x)^3] = 3*relu(x)^2` (zero for `x <= 0`):

```python
class CubedReLU(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        # kernel: v = max(x,0); out = v*v*v
        return ext.cubed_relu_fwd(x)

    @staticmethod
    def backward(ctx, grad_output):
        x, = ctx.saved_tensors
        # kernel: v=max(x,0); grad_in = grad_out * 3 * v * v
        return ext.cubed_relu_bwd(grad_output.contiguous(), x)
